insert into public.lessons (id, module_id, title, summary, order_index, video_url) values
  ('a3000000-0000-4000-8000-000000000101', 'a2000000-0000-4000-8000-000000000001', '1. Origen y sistemas de numeración', 'Sistemas aditivos y posicionales: egipcio, romano y decimal.', 1, null),
  ('a3000000-0000-4000-8000-000000000102', 'a2000000-0000-4000-8000-000000000001', '2. Aproximación por redondeo', 'Regla del redondeo y aproximaciones a distintos órdenes.', 2, null),
  ('a3000000-0000-4000-8000-000000000103', 'a2000000-0000-4000-8000-000000000001', '3. Suma y resta', 'Paréntesis, propiedades conmutativa y asociativa, problemas.', 3, null),
  ('a3000000-0000-4000-8000-000000000104', 'a2000000-0000-4000-8000-000000000001', '4. Multiplicación', 'Propiedades, distributiva y trucos de cálculo mental.', 4, null),
  ('a3000000-0000-4000-8000-000000000105', 'a2000000-0000-4000-8000-000000000001', '5. División y orden de operaciones', 'Divisiones exactas y enteras; prioridad de operaciones.', 5, null),
  ('a3000000-0000-4000-8000-000000000201', 'a2000000-0000-4000-8000-000000000002', '1. Potencias: base y exponente', 'Base, exponente, cuadrado, cubo, exponente cero y cálculo.', 1, null),
  ('a3000000-0000-4000-8000-000000000202', 'a2000000-0000-4000-8000-000000000002', '2. Potencias de base 10', 'Ceros y exponente; leer números grandes con potencias de 10.', 2, null),
  ('a3000000-0000-4000-8000-000000000203', 'a2000000-0000-4000-8000-000000000002', '3. Números grandes abreviados', 'Forma a · 10^n; ejemplo del año luz y cantidades reales.', 3, null),
  ('a3000000-0000-4000-8000-000000000204', 'a2000000-0000-4000-8000-000000000002', '4. Raíz cuadrada', 'Raíz exacta, raíz entera, cuadrados perfectos y problemas.', 4, null),
  ('a3000000-0000-4000-8000-000000000301', 'a2000000-0000-4000-8000-000000000003', '1. La relación de divisibilidad', 'División exacta, múltiplo y divisor; comprobar emparejamientos.', 1, null),
  ('a3000000-0000-4000-8000-000000000302', 'a2000000-0000-4000-8000-000000000003', '2. Múltiplos y divisores', 'Series de múltiplos, parejas de divisores y búsqueda sistemática.', 2, null),
  ('a3000000-0000-4000-8000-000000000303', 'a2000000-0000-4000-8000-000000000003', '3. Criterios de divisibilidad', 'Reglas para 2, 3, 5 y 10 sin dividir.', 3, null),
  ('a3000000-0000-4000-8000-000000000304', 'a2000000-0000-4000-8000-000000000003', '4. Números primos y compuestos', 'Factorización, primos menores que 30 y descomposición.', 4, null),
  ('a3000000-0000-4000-8000-000000000305', 'a2000000-0000-4000-8000-000000000003', '5. MCM y MCD', 'Método artesanal, problemas de coincidencia y reparto.', 5, null),
  ('a3000000-0000-4000-8000-000000000401', 'a2000000-0000-4000-8000-000000000004', '1. Números positivos y negativos', 'Opuestos, temperatura, dinero y notación con paréntesis.', 1, null),
  ('a3000000-0000-4000-8000-000000000402', 'a2000000-0000-4000-8000-000000000004', '2. Recta numérica y valor absoluto', 'Conjunto Z, orden, |a| y comparación.', 2, null),
  ('a3000000-0000-4000-8000-000000000403', 'a2000000-0000-4000-8000-000000000004', '3. Suma y resta de enteros', 'Mismo signo / distinto signo; dos métodos de cálculo.', 3, null),
  ('a3000000-0000-4000-8000-000000000404', 'a2000000-0000-4000-8000-000000000004', '4. Paréntesis con enteros', 'Quitar paréntesis, bloques y expresiones anidadas.', 4, null),
  ('a3000000-0000-4000-8000-000000000405', 'a2000000-0000-4000-8000-000000000004', '5. Multiplicación y división', 'Regla de signos y operaciones combinadas.', 5, null),
  ('a3000000-0000-4000-8000-000000000501', 'a2000000-0000-4000-8000-000000000005', '1. Los órdenes de unidades decimales', 'Lectura y escritura, recta numérica, orden, decimales intermedios y redondeo.', 1, null),
  ('a3000000-0000-4000-8000-000000000502', 'a2000000-0000-4000-8000-000000000005', '2. Operaciones con números decimales', 'Suma, resta y multiplicación; potencias de 10 y expresiones combinadas.', 2, null),
  ('a3000000-0000-4000-8000-000000000503', 'a2000000-0000-4000-8000-000000000005', '3. División de números decimales', 'Cociente decimal, aproximaciones y división entre potencias de 10.', 3, null),
  ('a3000000-0000-4000-8000-000000000601', 'a2000000-0000-4000-8000-000000000006', '1. Magnitudes y el Sistema Métrico Decimal', 'Medir magnitudes, historia del S.M.D., metro, litro, gramo y prefijos.', 1, null),
  ('a3000000-0000-4000-8000-000000000602', 'a2000000-0000-4000-8000-000000000006', '2. Medida de la longitud', 'Tabla de unidades, cambios con la coma, forma compleja e incompleja.', 2, null),
  ('a3000000-0000-4000-8000-000000000603', 'a2000000-0000-4000-8000-000000000006', '3. Medida de la capacidad', 'Litro y múltiplos; cambios de unidad y forma compleja.', 3, null),
  ('a3000000-0000-4000-8000-000000000604', 'a2000000-0000-4000-8000-000000000006', '4. Medida del peso', 'Gramo, kilogramo, tonelada; cambios y problemas.', 4, null),
  ('a3000000-0000-4000-8000-000000000605', 'a2000000-0000-4000-8000-000000000006', '5. Medida de la superficie', 'Metro cuadrado, unidades agrarias; cambios de cien en cien.', 5, null),
  ('a3000000-0000-4000-8000-000000000801', 'a2000000-0000-4000-8000-000000000008', '1. Parte de la unidad', 'Significado de fracción, numerador y denominador; menor, igual o mayor que la unidad.', 1, null),
  ('a3000000-0000-4000-8000-000000000802', 'a2000000-0000-4000-8000-000000000008', '2. La fracción como operador', 'Calcular una fracción de un número; cálculo mental y problemas.', 2, null),
  ('a3000000-0000-4000-8000-000000000803', 'a2000000-0000-4000-8000-000000000008', '3. Fracciones y números decimales', 'Fracción como división; paso a decimal y decimales periódicos.', 3, null),
  ('a3000000-0000-4000-8000-000000000804', 'a2000000-0000-4000-8000-000000000008', '4. Fracciones equivalentes', 'Propiedad fundamental, amplificar, simplificar e irreducibles.', 4, null),
  ('a3000000-0000-4000-8000-000000000805', 'a2000000-0000-4000-8000-000000000008', '5. Problemas con fracciones', 'Calcular la fracción, fracción de un número e inversos (parte conocida).', 5, null),
  ('a3000000-0000-4000-8000-000000000901', 'a2000000-0000-4000-8000-000000000009', '1. Reducción a común denominador', 'MCM de denominadores; fracciones equivalentes para comparar, ordenar y operar.', 1, null),
  ('a3000000-0000-4000-8000-000000000902', 'a2000000-0000-4000-8000-000000000009', '2. Suma y resta de fracciones', 'Mismo o distinto denominador; enteros como fracciones; simplificar resultados.', 2, null),
  ('a3000000-0000-4000-8000-000000000903', 'a2000000-0000-4000-8000-000000000009', '3. Multiplicación y división de fracciones', 'Producto de numeradores y denominadores; división en cruz; operaciones combinadas.', 3, null),
  ('a3000000-0000-4000-8000-000000000904', 'a2000000-0000-4000-8000-000000000009', '4. Problemas con fracciones', 'Suma sobre el total frente a fracción del resto; problemas contextualizados del temario.', 4, null),
  ('a3000000-0000-4000-8000-000000001001', 'a2000000-0000-4000-8000-000000000010', '1. Relación de proporcionalidad entre magnitudes', 'Magnitudes, tablas de valores, proporcionalidad directa e inversa.', 1, null),
  ('a3000000-0000-4000-8000-000000001002', 'a2000000-0000-4000-8000-000000000010', '2. Problemas de proporcionalidad directa', 'Reducción a la unidad, fracciones equivalentes y regla de tres directa.', 2, null),
  ('a3000000-0000-4000-8000-000000001003', 'a2000000-0000-4000-8000-000000000010', '3. Porcentajes', 'Tanto por ciento, fracción sobre 100, porcentajes especiales y calculadora.', 3, null),
  ('a3000000-0000-4000-8000-000000001004', 'a2000000-0000-4000-8000-000000000010', '4. Aumentos y disminuciones porcentuales', 'Subidas y rebajas de precios, intereses y variaciones porcentuales.', 4, null),
  ('a3000000-0000-4000-8000-000000001101', 'a2000000-0000-4000-8000-000000000011', '1. Letras en vez de números', 'Generalizar con letras, lenguaje algebraico y primer problema con ecuación.', 1, null),
  ('a3000000-0000-4000-8000-000000001102', 'a2000000-0000-4000-8000-000000000011', '2. Expresiones algebraicas', 'Monomios, suma y multiplicación; propiedad distributiva.', 2, null),
  ('a3000000-0000-4000-8000-000000001103', 'a2000000-0000-4000-8000-000000000011', '3. Ecuaciones', 'Ecuaciones e identidades; miembros, términos e incógnitas.', 3, null),
  ('a3000000-0000-4000-8000-000000001104', 'a2000000-0000-4000-8000-000000000011', '4. Primeras técnicas de resolución', 'Ecuaciones $x + a$, $x - a$, $ax$ y $x/a$; reglas de transposición.', 4, null),
  ('a3000000-0000-4000-8000-000000001105', 'a2000000-0000-4000-8000-000000000011', '5. Ecuaciones de primer grado', 'Reducir miembros, transponer términos y comprobar la solución.', 5, null),
  ('a3000000-0000-4000-8000-000000001106', 'a2000000-0000-4000-8000-000000000011', '6. Problemas con ecuaciones', 'Traducir enunciados, plantear ecuaciones y problemas contextualizados.', 6, null),
  ('a3000000-0000-4000-8000-000000000701', 'a2000000-0000-4000-8000-000000000007', '1. Ecuaciones lineales con dos incógnitas', 'Soluciones, representación gráfica y rectas horizontales/verticales.', 1, null),
  ('a3000000-0000-4000-8000-000000000702', 'a2000000-0000-4000-8000-000000000007', '2. Sistemas de ecuaciones lineales', 'Solución gráfica, sistemas compatibles, incompatibles e indeterminados.', 2, null),
  ('a3000000-0000-4000-8000-000000000703', 'a2000000-0000-4000-8000-000000000007', '3. Resolución de sistemas lineales', 'Métodos de sustitución, igualación y reducción con ejemplos animados.', 3, null),
  ('a3000000-0000-4000-8000-000000000704', 'a2000000-0000-4000-8000-000000000007', '4. Sistemas no lineales', 'Identificación, sustitución paso a paso y comprobación de soluciones.', 4, null),
  ('a3000000-0000-4000-8000-000000000705', 'a2000000-0000-4000-8000-000000000007', '5. Problemas con sistemas de ecuaciones', 'Traducir enunciados a sistemas y resolver problemas contextualizados.', 5, null);
